mapper.select:
SELECT


ORDER BY su.display_name, su.id
LIMIT #{size} OFFSET #{offset}

SELECT tmr.user_id, tmr.role FROM tenant_member_role tmr WHERE tmr.tenant_id = #{tenantId} AND tmr.del_flag = 0 AND tmr.user_id IN
#{uid}
ORDER BY tmr.role

SELECT suo.user_id, so.name AS org_name FROM sys_user_org suo JOIN sys_org so ON so.tenant_id = suo.tenant_id AND so.id = suo.org_id AND so.del_flag = 0 AND so.status = 'ACTIVE' WHERE suo.tenant_id = #{tenantId} AND suo.del_flag = 0 AND suo.user_id IN
#{uid}
ORDER BY so.name

mapper.delete:
DELETE FROM sys_user_org
WHERE tenant_id = #{tenantId}
  AND user_id = #{userId}

mapper.select:
SELECT count(*)
FROM sys_org so
WHERE so.tenant_id = #{tenantId}
  AND so.id = #{orgId}
  AND so.del_flag = 0
  AND so.status = 'ACTIVE'
